function d(s){return s?String(s).replace(/([a-z0-9])([A-Z])/g,"$1 $2").toLowerCase().split(new RegExp("[^a-z0-9一-鿿]+")).filter(t=>t&&(t.length>=2||new RegExp("[一-鿿]").test(t))):[]}function h(s){const a=[s.text||""],o=s.candidates&&s.candidates.length?s.candidates:s.best?[s.best]:[];for(const t of o)t&&t.value&&a.push(String(t.value)),t&&t.name&&a.push(String(t.name));return new Set(d(a.join(" ")))}function p(s,a,o){const t=h(o);let e=0;for(const r of d(s))t.has(r)&&(e+=3);for(const r of a||[])t.has(r)&&(e+=1);return(o.candidates&&o.candidates.length?o.candidates:o.best?[o.best]:[]).some(r=>r&&(r.by==="testid"||r.by==="css"&&/^#/.test(r.value||"")))&&(e+=.5),e}function l(s,a,o){const t=d(a);return(o||[]).map(e=>({el:e,score:p(s,t,e)})).sort((e,i)=>i.score-e.score)}function m(s,a){const o=a instanceof Set?a:new Set(a||[]),t=[],e=new Set,i=[],r=[];let f=0;for(const n of s||[])if(!(!n||!n.selector_fix)){f+=1,r.push(`${n.title||""} ${n.steps||""}`.trim());for(const c of n.selector_fix_keys||[])if(!(!c||e.has(c))){if(e.add(c),o.has(c)){i.push(c);continue}t.push(c)}}return{keys:t,skipped:i,caseCount:f,ctx:r.join(" ").trim().slice(0,400)}}function w(s,a,o){const t=d(a),e=[];for(const n of s||[])for(const c of o||[]){const u=p(n,t,c);u>0&&e.push({key:n,el:c,score:u})}e.sort((n,c)=>c.score-n.score);const i=new Set,r=new Set,f=new Map;for(const{key:n,el:c,score:u}of e)i.has(n)||r.has(c)||(i.add(n),r.add(c),f.set(n,{key:n,el:c,score:u}));return(s||[]).map(n=>f.get(n)||{key:n,el:null,score:0})}export{m as c,w as m,l as r};
